{
  "components": [
    {
      "type": "claim",
      "quote": "The energy label provides information about the fuel consumption (in litres per 100 kilometres), CO2 emissions (in grams per kilometre) and the energy efficiency of the vehicle.",
      "gist": "Energy label details fuel consumption, CO2 emissions, and energy efficiency of vehicles."
    },
    {
      "type": "claim",
      "quote": "It contributes to reducing the average fuel consumption of new cars.",
      "gist": "Energy label helps reduce average fuel consumption of new cars."
    },
    {
      "type": "obligation",
      "quote": "The label must be displayed in a clearly visible manner directly on the vehicle or in its immediate vicinity.",
      "gist": "Energy label must be visibly displayed on the vehicle or nearby."
    },
    {
      "type": "obligation",
      "quote": "The details included in the label as well as some further information also have to be displayed in advertisements, in online configuration tools and in sales material.",
      "gist": "Label details and additional info must be shown in ads, online tools, and sales material."
    },
    {
      "type": "entity",
      "quote": "The Energy label for cars",
      "gist": "Energy label system for cars"
    }
  ]
}
